135	// splitLines cuts content into physical lines, keeping each one's byte offset.
136	// A trailing \r is dropped from the text but the offsets stay absolute.
137	func splitLines(b []byte) []line {
138		var lines []line
139		start := 0
140		for i := 0; i <= len(b); i++ {
141			if i < len(b) && b[i] != '\n' {
142				continue
143			}
144			if i == len(b) && start == len(b) {
145				break
146			}
147			text := string(b[start:i])
148			text = strings.TrimSuffix(text, "\r")
149			lines = append(lines, line{off: start, text: text})
150			start = i + 1
151		}
152		return lines
153	}
154	
155	// escapeChar reads the `# escape=` parser directive, which only counts at the
156	// very top of the file.
157	func escapeChar(lines []line) byte {
158		for _, l := range lines {
159			m := directive.FindStringSubmatch(strings.TrimSpace(l.text))
160			if m == nil {
161				break
162			}
163			if strings.EqualFold(m[1], "escape") && len(m[2]) == 1 && (m[2] == "`" || m[2] == `\`) {
164				return m[2][0]
165			}
166		}
167		return '\\'
168	}
