170	// gather collects the physical lines of the instruction starting at lines[i],
171	// following the escape character across line breaks. Comment and blank lines
172	// inside a continuation are skipped, as Docker does.
173	func gather(lines []line, i int, esc byte) (pieces []piece, next int) {
174		for i < len(lines) {
175			text := strings.TrimRight(lines[i].text, " \t")
176			if text == "" || text[len(text)-1] != esc {
177				pieces = append(pieces, piece{off: lines[i].off, text: lines[i].text})
178				return pieces, i + 1
179			}
180			pieces = append(pieces, piece{off: lines[i].off, text: text[:len(text)-1]})
181			i++
182			for i < len(lines) {
183				t := strings.TrimSpace(lines[i].text)
184				if t != "" && !strings.HasPrefix(t, "#") {
185					break
186				}
187				i++
188			}
189		}
190		return pieces, i
191	}
