193	// tokenize splits pieces on spaces and tabs, with absolute byte spans.
194	func tokenize(pieces []piece) []token {
195		var tokens []token
196		for _, p := range pieces {
197			start := -1
198			for j := 0; j <= len(p.text); j++ {
199				space := j == len(p.text) || p.text[j] == ' ' || p.text[j] == '\t'
200				switch {
201				case !space && start < 0:
202					start = j
203				case space && start >= 0:
204					tokens = append(tokens, token{
205						span: Span{Start: p.off + start, End: p.off + j},
206						text: p.text[start:j],
207					})
208					start = -1
209				}
210			}
211		}
212		return tokens
213	}
