238	// readFrom reads what follows the FROM keyword: flags, the image, `AS name`.
239	func readFrom(tokens []token, args map[string]argValue, names map[string]bool) Stage {
240		var st Stage
241		i := 0
242		for i < len(tokens) && strings.HasPrefix(tokens[i].text, "--") {
243			if k, v, ok := strings.Cut(tokens[i].text, "="); ok && strings.EqualFold(k, "--platform") {
244				st.Platform = v
245			}
246			i++
247		}
248		if i >= len(tokens) {
249			st.Unresolved = "FROM names no image"
250			return st
251		}
252		image := tokens[i]
253		if i+2 < len(tokens) && strings.EqualFold(tokens[i+1].text, "AS") {
254			st.Name = tokens[i+2].text
255		}
256		st.Written = image.text
257	
258		switch {
259		case strings.EqualFold(image.text, "scratch"):
260			st.Kind = KindScratch
261		case names[strings.ToLower(image.text)]:
262			st.Kind = KindStage
263		default:
264			resolveImage(&st, image, args)
265		}
266		return st
267	}
