269	// resolveImage fills in Image, Span and Editable for an image token.
270	func resolveImage(st *Stage, image token, args map[string]argValue) {
271		resolved, ok, sole := expand(image.text, args)
272		if !ok {
273			st.Unresolved = "the reference uses a build arg with no default"
274			return
275		}
276		st.Image = resolved
277		if !strings.Contains(image.text, "$") {
278			st.Span, st.Editable = image.span, true
279			return
280		}
281		if sole != nil && sole.hasDefault {
282			// The whole reference is one variable: the default in its ARG line is
283			// where the image is written. A --build-arg on the command line can
284			// still override it, which a file cannot show.
285			st.Span, st.Editable = sole.span, true
286			return
287		}
288		st.NoEditReason = "the reference is assembled from build args, so no single place in the file spells it"
289	}
