291	var reference = regexp.MustCompile(`\$(?:\{([A-Za-z_][A-Za-z0-9_]*)(?:(:?-)([^}]*))?\}|([A-Za-z_][A-Za-z0-9_]*))`)
292	
293	// expand substitutes ${NAME}, $NAME, ${NAME:-default} and ${NAME-default}
294	// from the global ARGs. ok is false when a variable has no value; sole is the
295	// ARG when s is nothing but one reference to it.
296	func expand(s string, args map[string]argValue) (out string, ok bool, sole *argValue) {
297		ok = true
298		whole := reference.FindStringSubmatchIndex(s)
299		out = reference.ReplaceAllStringFunc(s, func(m string) string {
300			sub := reference.FindStringSubmatch(m)
301			name := sub[1]
302			if name == "" {
303				name = sub[4]
304			}
305			a, declared := args[name]
306			switch {
307			case declared && a.hasDefault && (a.value != "" || sub[2] != ":-"):
308				return a.value
309			case sub[2] != "":
310				return sub[3]
311			}
312			ok = false
313			return m
314		})
315		if whole != nil && whole[0] == 0 && whole[1] == len(s) {
316			sub := reference.FindStringSubmatch(s)
317			name := sub[1]
318			if name == "" {
319				name = sub[4]
320			}
321			if a, declared := args[name]; declared {
322				sole = &a
323			}
324		}
325		return out, ok, sole
326	}
