142	// The block goes before the final stage's first CMD or ENTRYPOINT, which is
143	// where it has to be to apply to the process that runs — after it, it would
144	// change nothing. With neither, it goes at the end of the file.
145	//
146	// What it does not do is chown anything. A process that loses root may no longer
147	// be able to write where it used to, and no edit computed from the Dockerfile
148	// alone can know. That is a change the user reads in the diff and agrees to, and
149	// that the re-scan then confirms cleared the rule — it is not a claim that the
150	// image still works.
151	func fixRootUser(content []byte, f scan.Finding) ([]patch.Edit, string) {
152		if !dockerfile.IsDockerfileName(baseName(f.File)) {
153			return nil, ReasonNotADockerfile
154		}
155		stages := dockerfile.Parse(content).Stages
156		if len(stages) == 0 {
157			return nil, ReasonNoStage
158		}
159	
160		final := stages[len(stages)-1]
161		if !isDebianFamily(final.Image) {
