182	// addUserBlock is the Debian/Ubuntu incantation, spelled out rather than
183	// condensed: every flag is there to make the account unusable for anything but
184	// running the process — no password, no home, no login shell.
185	func addUserBlock(eol string) string {
186		lines := []string{
187			"ARG UID=" + nonRootUID,
188			"RUN adduser \\",
189			`    --disabled-password \`,
190			`    --gecos "" \`,
191			`    --home "/nonexistent" \`,
192			`    --shell "/usr/sbin/nologin" \`,
193			"    --no-create-home \\",
194			`    --uid "${UID}" \`,
195			"    " + nonRootUser,
196			"USER " + nonRootUser,
197		}
198		return strings.Join(lines, eol) + eol
