201	// debianFamilyBases are the official images that build on Debian or Ubuntu
202	// unless their tag says otherwise.
203	//
204	// The list is short and conservative on purpose: an image missing from it is
205	// declined, which costs a fix, while an image wrongly in it emits a RUN that
206	// fails at build. A private base (`registry.example.com/base:1`) says nothing
207	// about its distribution and is therefore never accepted.
208	var debianFamilyBases = map[string]bool{
209		"debian": true, "ubuntu": true,
210		"golang": true, "node": true, "python": true, "ruby": true,
211		"rust": true, "php": true, "perl": true, "openjdk": true,
212		"maven": true, "gradle": true, "eclipse-temurin": true,
213	}
