215	// isDebianFamily says whether ref's adduser takes Debian's flags.
216	//
217	// An "alpine" anywhere in the reference disqualifies it whatever the repository
218	// says — `golang:1.23-alpine` is busybox — and so does a digest with no tag,
219	// where nothing names the variant.
220	func isDebianFamily(ref string) bool {
221		if ref == "" {
222			return false
223		}
224		lower := strings.ToLower(ref)
225		if strings.Contains(lower, "alpine") || strings.Contains(lower, "busybox") ||
226			strings.Contains(lower, "distroless") || strings.Contains(lower, "scratch") {
227			return false
228		}
