242	// lineEnding returns what this file separates its lines with, so an inserted
243	// block does not mix LF into a CRLF file.
244	func lineEnding(content []byte) string {
245		if i := indexByte(content, '\n'); i > 0 && content[i-1] == '\r' {
246			return "\r\n"
247		}
248		return "\n"
249	}
