260	// insertionPoint finds where a USER instruction has to go in the stage that
261	// starts at the 1-based line finalFrom: just before that stage's first CMD or
262	// ENTRYPOINT, or at eof when it has neither.
263	//
264	// It also answers whether the stage already sets a user, because that is the
265	// same single pass — asking twice would let the two answers disagree about
266	// where the stage ends.
267	func insertionPoint(lines []contentLine, finalFrom, eof int) (at int, alreadySet bool) {
268		for i := finalFrom; i < len(lines); i++ {
269			switch instruction(lines[i].text) {
270			case "USER":
271				return 0, true
272			case "CMD", "ENTRYPOINT":
273				return lines[i].off, false
274			}
275		}
276		return eof, false
277	}
278	
279	// instruction returns the leading keyword of a Dockerfile line, uppercased, or
280	// "" for a blank line, a comment, or a continuation of the line before it.
281	//
282	// It does not follow continuations, and does not need to: it is only ever asked
283	// whether a line *starts* an instruction, and a continued line never does.
284	func instruction(text string) string {
285		t := strings.TrimSpace(text)
286		if t == "" || strings.HasPrefix(t, "#") {
287			return ""
288		}
289		word, _, _ := strings.Cut(t, " ")
290		word, _, _ = strings.Cut(word, "\t")
291		return strings.ToUpper(word)
292	}
293	
294	type contentLine struct {
295		off  int
296		text string
297	}
298	
299	// contentLines cuts content into lines, keeping each one's byte offset so an
300	// edit can be placed at the start of one.
301	func contentLines(content []byte) []contentLine {
302		var out []contentLine
303		start := 0
304		for i := 0; i <= len(content); i++ {
305			if i < len(content) && content[i] != '\n' {
306				continue
307			}
308			if i == len(content) && start == len(content) {
309				break
310			}
311			out = append(out, contentLine{off: start, text: strings.TrimSuffix(string(content[start:i]), "\r")})
312			start = i + 1
313		}
314		return out
315	}
316	
317	func endsWithNewline(content []byte) bool {
318		return len(content) > 0 && content[len(content)-1] == '\n'
319	}
