321	// baseName is filepath.Base for a path Trivy reported, which always uses
322	// forward slashes whatever the host.
323	func baseName(p string) string {
324		if i := strings.LastIndexByte(p, '/'); i >= 0 {
325			return p[i+1:]
326		}
327		return p
328	}
