3	import (
4		"io/fs"
5		"path/filepath"
6		"sort"
7		"strings"
8	)
9	
10	const (
11		// maxFindDepth bounds how far below the root a Dockerfile is looked for:
12		// a monorepo keeps them a few levels down, and a tree deeper than that is
13		// vendored or generated.
14		maxFindDepth = 4
15		// maxFound bounds the answer, so a checkout that vendors hundreds of
16		// example Dockerfiles cannot turn one keypress into hundreds of registry
17		// requests.
18		maxFound = 50
19	)
20	
21	// skippedDirs are never entered: what a package manager or a VCS put there is
22	// not the project's own build.
23	var skippedDirs = map[string]bool{
24		".git": true, "node_modules": true, "vendor": true, ".worktrees": true,
25		".venv": true, "venv": true, "target": true, "dist": true, "build": true,
26	}
27	
28	// IsDockerfileName reports whether a file name is one a container build reads:
29	// Dockerfile or Containerfile, with a suffix (Dockerfile.dev) or a prefix
30	// (api.Dockerfile). It is by name and never by content, as the viewer's kind
31	// detection is.
32	func IsDockerfileName(name string) bool {
33		lower := strings.ToLower(name)
34		for _, base := range []string{"dockerfile", "containerfile"} {
35			if lower == base || strings.HasPrefix(lower, base+".") || strings.HasSuffix(lower, "."+base) {
36				return true
37			}
38		}
39		return false
40	}
41	
42	// Find lists the Dockerfiles under root, as slash-separated paths relative to
43	// it, in path order. It reports whether the answer was cut at the bound.
44	func Find(root string) (paths []string, truncated bool, err error) {
45		err = filepath.WalkDir(root, func(path string, d fs.DirEntry, walkErr error) error {
46			if walkErr != nil {
47				if path == root {
48					return walkErr
49				}
50				return nil // an unreadable subdirectory is skipped, not fatal
51			}
52			rel, relErr := filepath.Rel(root, path)
53			if relErr != nil {
54				return nil
55			}
56			if d.IsDir() {
57				if rel != "." && (skippedDirs[d.Name()] || strings.Count(rel, string(filepath.Separator)) >= maxFindDepth) {
58					return filepath.SkipDir
59				}
60				return nil
61			}
62			if IsDockerfileName(d.Name()) {
63				paths = append(paths, filepath.ToSlash(rel))
64			}
65			return nil
66		})
67		if err != nil {
68			return nil, false, err
69		}
70		sort.Strings(paths)
71		if len(paths) > maxFound {
72			return paths[:maxFound], true, nil
73		}
74		return paths, false, nil
75	}
