func TestTheFlagIsAddedRightAfterInstall(t *testing.T) {
	src := "FROM debian:12\nRUN apt-get install -y curl\n"
	got, reason := apply(t, src, misconfLines("AVD-DS-0029", "Dockerfile", 2, 2))
	if reason != "" {
		t.Fatalf("declined: %s", reason)
